type Tab = "today" | "leads" | "opportunities" | "scripts" | "hunt" | "analytics";
type HuntedLead = { id: string; name: string; phone?: string; whatsapp?: string; site?: string; segment: string; location: string; score: number; opportunity: string; sourceUrl: string; sourceTitle: string; confidence: string };

type ResearchSummary = { lastResearchAt: string; researchHash: string; sources: Array<{ id: string; claim: string; sourceUrl: string; sourceType: string; sourceTitle: string; retrievedAt: string; confidence: string }>; signals: string[]; opportunities: string[] };
