function normalizePhone(phone: string) { const digits = phone.replace(/\D/g, ""); return digits.startsWith("55") ? digits : `55${digits}`; }
function normalize(value: string) { return value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ").trim(); }
function buildMessage(lead: Lead, stage: string) { const intel = lead.intelligence ?? analyzeLead(lead); const signal = intel.observedSignals[0]; const pain = intel.probablePains[0]; const prefix = stage === "follow-up" ? "Oi, retomando nossa conversa" : stage === "qualificação" ? "Para entender melhor" : "Oi"; return `${prefix}, responsável pela ${lead.name}. ${signal ? `Vi ${signal} por aí. ` : ""}Hoje vocês controlam ${pain.toLowerCase()} por onde? Estou pesquisando como empresas de ${intel.subsegment} organizam essa rotina e posso compartilhar uma ideia rápida, sem compromisso.`; }
function isDue(lead: Lead) { return Boolean(lead.nextActionAt && new Date(lead.nextActionAt).getTime() <= Date.now()); }
function isToday(lead: Lead) { if (!lead.nextActionAt) return false; const d = new Date(lead.nextActionAt); const now = new Date(); return d.toDateString() === now.toDateString(); }
function priorityReason(lead: Lead) { if (isDue(lead)) return "Follow-up vencido: precisa de atenção agora."; const status = lead.status; if (status === "Respondeu") return "Há uma resposta pendente para tratar."; if (status === "Reunião") return "Reunião marcada: preparar o próximo passo."; if (lead.score >= 85 && lead.phone) return "Alta aderência, contato disponível e oportunidade comercial clara."; return "Prioridade baseada no score e na aderência do segmento."; }
function buildVariants(lead: Lead) { const intel = lead.intelligence ?? analyzeLead(lead); const subject = intel.subsegment || lead.segment; const pain = intel.probablePains[0].toLowerCase(); return { Direta: `Oi! Vi a ${lead.name} e queria te perguntar: hoje vocês controlam ${pain} por onde?`, Consultiva: `Estou pesquisando como empresas de ${subject} organizam ${pain}. A ${lead.name} já usa algum processo ou sistema para isso? Se fizer sentido, compartilho uma ideia rápida.`, Natural: `Oi, tudo certo? Encontrei a ${lead.name} pesquisando empresas de ${subject} em Belém. Fiquei curioso: como vocês lidam hoje com ${pain}?` }; }

function parseCsv(text: string): { rows: string[][]; separator: string } { const separator = (text.split(/\r?\n/)[0].match(/;/g)?.length ?? 0) >= (text.split(/\r?\n/)[0].match(/,/g)?.length ?? 0) ? ";" : ","; const rows: string[][] = []; for (const line of text.split(/\r?\n/).filter(Boolean)) { const cells: string[] = []; let cell = "", quoted = false; for (let i = 0; i < line.length; i++) { const c = line[i]; if (c === '"') quoted = !quoted; else if (c === separator && !quoted) { cells.push(cell.trim()); cell = ""; } else cell += c; } cells.push(cell.trim()); rows.push(cells); } return { rows, separator }; }

export default function Home() {
  const [allLeads, setAllLeads] = useState<Lead[]>(() => { try { const saved = localStorage.getItem("prospecta-leads-v2"); return saved ? JSON.parse(saved) : [...additionalImportedLeads, ...spreadsheetImportedLeads, ...leads]; } catch { return [...additionalImportedLeads, ...spreadsheetImportedLeads, ...leads]; } });
  const [statuses, setStatuses] = useState<Record<string, LeadStatus>>(() => { try { return JSON.parse(localStorage.getItem("prospecta-statuses-v2") || "{}"); } catch { return {}; } });
  const [toast, setToast] = useState<string | null>(null); const [activeTab, setActiveTab] = useState<Tab>("today"); const [huntedResults, setHuntedResults] = useState<HuntedLead[]>([]); const [huntSelected, setHuntSelected] = useState<string[]>([]); const [huntPreset, setHuntPreset] = useState<{ segment: string; location: string } | undefined>(); const [segment, setSegment] = useState<"Todos" | Segment>("Todos"); const [query, setQuery] = useState(""); const [priority, setPriority] = useState<"Todas" | Priority>("Todas"); const [selectedLead, setSelectedLead] = useState<Lead | null>(null); const [showAddLead, setShowAddLead] = useState(false); const [copied, setCopied] = useState<string | null>(null); const [importSummary, setImportSummary] = useState<string | null>(null); const [newLead, setNewLead] = useState({ name: "", segment: "Serviços" as Segment, phone: "", email: "", location: "Belém · PA", pain: "" });
  useEffect(() => { localStorage.setItem("prospecta-leads-v2", JSON.stringify(allLeads)); }, [allLeads]); useEffect(() => { localStorage.setItem("prospecta-statuses-v2", JSON.stringify(statuses)); }, [statuses]);
  const enriched = useMemo(() => allLeads.map((lead) => ({ ...lead, status: statuses[lead.id] || "Novo", intelligence: lead.intelligence ?? analyzeLead(lead), service: lead.service ?? serviceBySegment[lead.segment] })), [allLeads]);
  const filtered = useMemo(() => enriched.filter((lead) => { const q = normalize(query); return (segment === "Todos" || lead.segment === segment) && (priority === "Todas" || lead.priority === priority) && (!q || normalize(`${lead.name} ${lead.segment} ${lead.location} ${lead.pain} ${lead.opportunity}`).includes(q)); }), [enriched, query, segment, priority]);
  const stats = useMemo(() => ({ total: enriched.length, high: enriched.filter((l) => l.priority === "Alta").length, contacted: enriched.filter((l) => ["Mensagem enviada", "Aguardando resposta", "Respondeu", "Qualificado", "Reunião", "Proposta", "Ganho"].includes(statuses[l.id])).length, replies: enriched.filter((l) => ["Respondeu", "Qualificado", "Reunião", "Proposta", "Ganho"].includes(statuses[l.id])).length, meetings: enriched.filter((l) => statuses[l.id] === "Reunião").length }), [enriched, statuses]);
  const best = [...enriched].sort((a, b) => b.score - a.score)[0];
  function updateLead(id: string, patch: Partial<Lead>) { setAllLeads((current) => current.map((lead) => lead.id === id ? { ...lead, ...patch } : lead)); setSelectedLead((current) => current?.id === id ? { ...current, ...patch } : current); }
  function notify(message: string) { setToast(message); window.setTimeout(() => setToast(null), 2200); }
  function updateStatus(id: string, value: LeadStatus) { setStatuses((current) => ({ ...current, [id]: value })); const lead = enriched.find((l) => l.id === id); if (lead) { updateLead(id, { events: [...(lead.events || []), { id: crypto.randomUUID(), type: `Status alterado para ${value}`, at: new Date().toISOString() }], nextAction: value === "Respondeu" ? "responder" : value === "Reunião" ? "agendar" : value === "Mensagem enviada" ? "follow-up" : lead.nextAction }); notify(value === "Mensagem enviada" ? "Mensagem marcada como enviada" : `Status atualizado: ${value}`); } }
  function openWhatsApp(lead: Lead) { window.open(`https://wa.me/${normalizePhone(lead.phone)}?text=${encodeURIComponent(buildMessage(lead, "primeiro contato"))}`, "_blank", "noopener,noreferrer"); updateLead(lead.id, { events: [...(lead.events || []), { id: crypto.randomUUID(), type: "WhatsApp aberto (não significa mensagem enviada)", at: new Date().toISOString() }], nextAction: "abordar" }); notify("WhatsApp aberto"); }
  function prepareMessage(lead: Lead) { updateLead(lead.id, { events: [...(lead.events || []), { id: crypto.randomUUID(), type: "Mensagem preparada", at: new Date().toISOString() }], nextAction: "abordar" }); setSelectedLead(lead); notify("Mensagem preparada"); }
  async function copyText(key: string, text: string) { try { await navigator.clipboard.writeText(text); setCopied(key); notify("Mensagem copiada"); setTimeout(() => setCopied(null), 1600); } catch { setCopied(null); } }
  function addManualLead(event: FormEvent) { event.preventDefault(); if (!newLead.name.trim() || !newLead.phone.trim()) return; const name = newLead.name.trim(); const created: Lead = { id: `manual-${Date.now()}`, name, segment: newLead.segment, phone: newLead.phone, email: newLead.email || undefined, location: newLead.location, priority: "Alta", score: 60, pain: newLead.pain || "Ainda não diagnosticada", opportunity: serviceBySegment[newLead.segment], initials: name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase(), color: "lime", demo: false }; setAllLeads((current) => [created, ...current]); setNewLead({ name: "", segment: "Serviços", phone: "", email: "", location: "Belém · PA", pain: "" }); setShowAddLead(false); }
  function handleCsvImport(event: ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const { rows } = parseCsv(String(reader.result || "")); if (rows.length < 2) return setImportSummary("Nenhuma linha válida encontrada."); const headers = rows[0].map(normalize); const find = (row: string[], names: string[]) => row[headers.findIndex((h) => names.includes(h))] || ""; const valid: Lead[] = []; let incomplete = 0, duplicates = 0; for (let index = 0; index < rows.slice(1).length; index++) {
const row = rows.slice(1)[index]; const name = find(row, ["empresa", "nome", "razao social"]); const phone = find(row, ["telefone", "whatsapp", "celular"]); if (!name || !phone) { incomplete++; continue; } const duplicate = enriched.some((l) => normalizePhone(l.phone) === normalizePhone(phone) || (l.site && find(row, ["site", "dominio"]) && normalize(l.site) === normalize(find(row, ["site", "dominio"]))) || normalize(l.name) === normalize(name)); if (duplicate) { duplicates++; continue; } const rawSegment = normalize(find(row, ["segmento", "categoria"])); const leadSegment: Segment = rawSegment.includes("imob") ? "Imobiliárias" : rawSegment.includes("distrib") || rawSegment.includes("material") ? "Distribuidoras" : "Serviços"; valid.push({ id: `csv-${Date.now()}-${index}`, name, phone, segment: leadSegment, location: find(row, ["local", "cidade", "endereco"]) || "Belém · PA", email: find(row, ["email"]) || undefined, site: find(row, ["site", "dominio"]) || undefined, priority: "Média", score: 60, pain: find(row, ["dor", "problema"]) || "A investigar", opportunity: find(row, ["oportunidade", "servico"]) || serviceBySegment[leadSegment], initials: name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase(), color: colors[index % colors.length], demo: false }); } setAllLeads((current) => [...valid, ...current]); setImportSummary(`${valid.length} importadas · ${duplicates} duplicadas · ${incomplete} incompletas`); }; reader.readAsText(file, "UTF-8"); event.target.value = ""; }
  async function hunt(segment: string, location: string, quantity: number) { const response = await fetch("/api/hunt-leads", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ segment, location, quantity }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "Falha na busca"); const existing = new Set(enriched.map((l) => normalize(l.name))); const unique = result.results.filter((item: HuntedLead) => !existing.has(normalize(item.name))); setHuntedResults(unique); setHuntSelected(unique.map((item: HuntedLead) => item.id)); return { found: result.results.length, unique: unique.length }; }
  function addHunted() { const chosen = huntedResults.filter((item) => huntSelected.includes(item.id)); const created: Lead[] = chosen.map((item, index) => ({ id: `hunted-${item.id}`, name: item.name, segment: (item.segment.includes("imob") ? "Imobiliárias" : item.segment.includes("distrib") ? "Distribuidoras" : "Serviços") as Segment, location: item.location, phone: item.phone || "", email: undefined, site: item.site, priority: item.score >= 80 ? "Alta" : "Média", score: item.score, pain: "A investigar", opportunity: item.opportunity, initials: item.name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase(), color: colors[index % colors.length], service: item.opportunity, demo: false })); setAllLeads((current) => [...created, ...current]); setHuntedResults((current) => current.filter((item) => !huntSelected.includes(item.id))); setHuntSelected([]); }
  async function researchLead(lead: Lead) { setSelectedLead((current) => current?.id === lead.id ? { ...current, researchLoading: true } as Lead : current); try { const response = await fetch("/api/research", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: lead.id, name: lead.name, site: lead.site, segment: lead.segment }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "Falha na pesquisa"); if (result.record) updateLead(lead.id, { research: result.record, score: Math.min(98, lead.score + result.record.signals.length * 3), events: [...(lead.events || []), { id: crypto.randomUUID(), type: `Pesquisa realizada: ${result.record.sources.length} fonte(s), ${result.record.signals.length} sinal(is)`, at: new Date().toISOString() }] }); else setSelectedLead((current) => current?.id === lead.id ? { ...current, researchLoading: false } as Lead : current); } catch (error) { setSelectedLead((current) => current?.id === lead.id ? { ...current, researchError: error instanceof Error ? error.message : "Falha na pesquisa" } as Lead : current); } }
  function scheduleFollowUp(lead: Lead, days: number) { const date = new Date(); date.setDate(date.getDate() + days); updateLead(lead.id, { nextAction: "follow-up", nextActionAt: date.toISOString(), events: [...(lead.events || []), { id: crypto.randomUUID(), type: `Follow-up programado para ${date.toLocaleDateString("pt-BR")}`, at: new Date().toISOString() }] }); notify(`Follow-up criado para ${date.toLocaleDateString("pt-BR")}`); }
  function huntFromLead(lead: Lead) { setHuntPreset({ segment: lead.intelligence?.subsegment || lead.segment, location: lead.location.split("·").pop()?.trim() || "Belém" }); setActiveTab("hunt"); }
  const nav = (tab: Tab) => setActiveTab(tab);
  return <div className="app-shell"><aside className="sidebar"><div className="brand-lockup"><div className="brand-mark"><Zap size={18} /></div><div><strong>Prospecta</strong><span>Assistente comercial · Belém</span></div></div><div className="sidebar-section-label">Workspace</div><nav className="side-nav"><button className={`nav-item ${activeTab === "today" ? "active" : ""}`} onClick={() => nav("today")}><Sparkles size={17} /> Hoje <span className="nav-count lime-count">{stats.high}</span></button><button className={`nav-item ${activeTab === "hunt" ? "active" : ""}`} onClick={() => nav("hunt")}><Search size={17} /> Caçar Leads <span className="nav-dot" /></button><button className={`nav-item ${activeTab === "analytics" ? "active" : ""}`} onClick={() => nav("analytics")}><BarChart3 size={17} /> Resultados</button><button className={`nav-item ${activeTab === "leads" ? "active" : ""}`} onClick={() => nav("leads")}><LayoutDashboard size={17} /> Leads <span className="nav-count">{stats.total}</span></button><button className={`nav-item ${activeTab === "opportunities" ? "active" : ""}`} onClick={() => nav("opportunities")}><Target size={17} /> Oportunidades <span className="nav-count">{stats.high}</span></button><button className={`nav-item ${activeTab === "scripts" ? "active" : ""}`} onClick={() => nav("scripts")}><MessageCircle size={17} /> Playbook</button></nav><div className="sidebar-section-label">Atalhos</div><div className="shortcut-list"><button onClick={() => { setSegment("Serviços"); nav("leads"); }}><span className="shortcut-icon orange-bg"><Settings2 size={15} /></span> Serviços técnicos</button><button onClick={() => { setSegment("Imobiliárias"); nav("leads"); }}><span className="shortcut-icon cyan-bg"><Globe2 size={15} /></span> Imobiliárias</button><button onClick={() => { setSegment("Distribuidoras"); nav("leads"); }}><span className="shortcut-icon violet-bg"><Inbox size={15} /></span> Distribuidoras</button></div><div className="sidebar-bottom"><div className="mini-profile"><div className="profile-avatar">VO</div><div><strong>Pipeline local</strong><span>Salvo neste navegador</span></div><MoreHorizontal size={17} /></div><div className="privacy-note"><Check size={13} /> Inferências marcadas como prováveis</div></div></aside><main className="main-content"><header className="topbar"><div className="breadcrumbs"><span>Workspace</span><span className="slash">/</span><strong>{activeTab === "analytics" ? "Resultados" : activeTab === "hunt" ? "Caçar Leads" : activeTab === "today" ? "Hoje" : activeTab === "leads" ? "Leads" : activeTab === "opportunities" ? "Oportunidades" : "Playbook"}</strong></div><div className="top-actions"><div className="live-status"><span className="live-dot" /> Belém, PA</div><div className="profile-avatar top-profile">VO</div></div></header>
    {activeTab === "analytics" && <AnalyticsPanel leads={enriched} statuses={statuses} />}
    {activeTab === "hunt" && <HuntPage results={huntedResults} selected={huntSelected} setSelected={setHuntSelected} onSearch={hunt} onAdd={addHunted} onOpen={(item) => window.open(item.sourceUrl, "_blank", "noopener,noreferrer")} preset={huntPreset} />}
    {activeTab === "today" && <Today best={best} queue={[...enriched].sort((a, b) => (Number(isDue(b)) - Number(isDue(a))) || b.score - a.score).slice(0, 8)} stats={stats} onSelect={(lead) => { setSelectedLead(lead); }} onOpen={openWhatsApp} onPrepare={prepareMessage} onNavigate={nav} />}
    {activeTab === "leads" && <LeadsPage filtered={filtered} stats={stats} query={query} setQuery={setQuery} segment={segment} setSegment={setSegment} priority={priority} setPriority={setPriority} statuses={statuses} updateStatus={updateStatus} openWhatsApp={openWhatsApp} setSelectedLead={setSelectedLead} setShowAddLead={setShowAddLead} handleCsvImport={handleCsvImport} importSummary={importSummary} />}
    {activeTab === "opportunities" && <Opportunities leads={enriched} statuses={statuses} onSelect={setSelectedLead} onOpen={openWhatsApp} onHunt={huntFromLead} />}
    {activeTab === "scripts" && <Scripts onCopy={copyText} copied={copied} />}
    <div className={`toast ${toast ? "show" : ""}`} role="status">{toast}</div></main>{showAddLead && <div className="modal-backdrop" onClick={() => setShowAddLead(false)}><form className="lead-modal lead-form" onSubmit={addManualLead} onClick={(e) => e.stopPropagation()}><button type="button" className="modal-close" onClick={() => setShowAddLead(false)}><X size={18} /></button><span className="modal-kicker">CADASTRO MANUAL</span><h2>Nova empresa</h2><div className="form-grid"><label>Empresa<input required value={newLead.name} onChange={(e) => setNewLead({ ...newLead, name: e.target.value })} /></label><label>Segmento<select value={newLead.segment} onChange={(e) => setNewLead({ ...newLead, segment: e.target.value as Segment })}><option>Serviços</option><option>Imobiliárias</option><option>Distribuidoras</option></select></label><label>Telefone<input required value={newLead.phone} onChange={(e) => setNewLead({ ...newLead, phone: e.target.value })} /></label><label>E-mail<input value={newLead.email} onChange={(e) => setNewLead({ ...newLead, email: e.target.value })} /></label><label>Localização<input value={newLead.location} onChange={(e) => setNewLead({ ...newLead, location: e.target.value })} /></label><label>Sinal observado<input value={newLead.pain} onChange={(e) => setNewLead({ ...newLead, pain: e.target.value })} placeholder="Ex.: equipe externa" /></label></div><div className="service-preview"><FileText size={16} /><span>O sistema investigará</span><strong>dor, oportunidade e serviço sugerido</strong></div><div className="modal-actions"><button type="submit" className="dark-action"><Plus size={16} /> Adicionar ao pipeline</button><button type="button" className="outline-button" onClick={() => setShowAddLead(false)}>Cancelar</button></div></form></div>}{selectedLead && <LeadModal lead={selectedLead} status={statuses[selectedLead.id] || "Novo"} onClose={() => setSelectedLead(null)} onOpen={openWhatsApp} onPrepare={prepareMessage} onCopy={copyText} copied={copied} onStatus={updateStatus} onUpdate={updateLead} onSchedule={scheduleFollowUp} onResearch={researchLead} onHunt={huntFromLead} />}</div>;
}

function AnalyticsPanel({ leads, statuses }: { leads: Lead[]; statuses: Record<string, LeadStatus> }) { const [segment, setSegment] = useState<"Todos" | Segment>("Todos"); const [channel, setChannel] = useState("Todos"); const segments: Segment[] = ["Serviços", "Distribuidoras", "Imobiliárias"]; const channelNames = ["Todos", "Telefone", "WhatsApp", "Site", "Instagram", "E-mail"]; const advanced = new Set<LeadStatus>(["Respondeu", "Qualificado", "Reunião", "Proposta", "Negociação", "Ganho"]); const qualified = new Set<LeadStatus>(["Qualificado", "Reunião", "Proposta", "Negociação", "Ganho"]); const meetings = new Set<LeadStatus>(["Reunião", "Proposta", "Negociação", "Ganho"]); const hasChannel = (lead: Lead) => channel === "Todos" || channel === "Telefone" || channel === "WhatsApp" ? Boolean(lead.phone) : channel === "Site" ? Boolean(lead.site) : channel === "Instagram" ? Boolean(lead.instagram) : Boolean(lead.email); const base = leads.filter((lead) => segment === "Todos" || lead.segment === segment); const channelBase = base.filter(hasChannel); const countStatus = (set: Set<LeadStatus>, pool = channelBase) => pool.filter((lead) => set.has(statuses[lead.id])).length; const pct = (n: number, d: number) => d ? `${(n / d * 100).toFixed(1).replace(".", ",")}%` : "—"; const segmentRows = segments.map((name) => { const pool = leads.filter((lead) => lead.segment === name && hasChannel(lead)); const answered = countStatus(advanced, pool); const qual = countStatus(qualified, pool); const meet = countStatus(meetings, pool); return { name, total: pool.length, answered, qual, meet, answerRate: pct(answered, pool.length), qualRate: pct(qual, answered), meetRate: pct(meet, qual) }; }); const stages = [{ label: "Base com canal", value: channelBase.length }, { label: "Respostas", value: countStatus(advanced) }, { label: "Qualificados", value: countStatus(qualified) }, { label: "Reuniões ou avanço", value: countStatus(meetings) }]; const max = Math.max(...stages.map((x) => x.value), 1); return <div className="page-content"><section className="hero-row"><div><div className="eyebrow"><BarChart3 size={13} /> RESULTADOS · CONVERSÃO</div><h1>Canais que <em>avançam.</em></h1><p>Compare a disponibilidade dos canais com os resultados realmente registrados no funil. A taxa só é calculada sobre eventos existentes.</p></div><div className="hero-tip"><div className="tip-icon"><BarChart3 size={17} /></div><div><span>Base analisada</span><strong>{base.length} empresas</strong><small>{channelBase.length} com {channel === "Todos" ? "algum canal" : channel.toLowerCase()} disponível</small></div></div></section><section className="analytics-filters"><label>Segmento<select value={segment} onChange={(e) => setSegment(e.target.value as "Todos" | Segment)}><option>Todos</option>{segments.map((x) => <option key={x}>{x}</option>)}</select></label><label>Canal analisado<select value={channel} onChange={(e) => setChannel(e.target.value)}>{channelNames.map((x) => <option key={x}>{x}</option>)}</select></label><div className="analytics-note"><strong>Regra:</strong> resposta = Respondeu ou estágio posterior; conversão não é estimada.</div></section><section className="analytics-kpis"><div><span>Disponibilidade do canal</span><strong>{pct(channelBase.length, base.length)}</strong><small>{channelBase.length} de {base.length}</small></div><div><span>Taxa de resposta</span><strong>{pct(countStatus(advanced), channelBase.length)}</strong><small>{countStatus(advanced)} respostas registradas</small></div><div><span>Taxa de qualificação</span><strong>{pct(countStatus(qualified), countStatus(advanced))}</strong><small>{countStatus(qualified)} qualificados</small></div><div><span>Taxa de avanço</span><strong>{pct(countStatus(meetings), countStatus(qualified))}</strong><small>{countStatus(meetings)} reuniões/propostas/ganhos</small></div></section><div className="analytics-layout"><section className="analytics-card"><div className="section-heading"><div><h2>Funil do canal selecionado</h2><span>{channel === "Todos" ? "Todos os canais cadastrados" : channel}</span></div></div><div className="funnel-bars">{stages.map((stage) => <div className="funnel-row" key={stage.label}><div><span>{stage.label}</span><b>{stage.value}</b></div><i style={{ width: `${stage.value / max * 100}%` }} /></div>)}</div>{channelBase.length === 0 && <p className="analytics-empty">Ainda não há contatos com este canal nesta seleção.</p>}{channelBase.length > 0 && countStatus(advanced) === 0 && <p className="analytics-empty">Ainda não há respostas registradas para calcular conversão histórica.</p>}</section><section className="analytics-card"><div className="section-heading"><div><h2>Comparação por segmento</h2><span>Disponibilidade e avanço do canal</span></div></div><div className="segment-table"><div className="segment-table-head"><span>Segmento</span><span>Base</span><span>Resposta</span><span>Qualif.</span><span>Avanço</span></div>{segmentRows.map((row) => <div className="segment-table-row" key={row.name}><strong>{row.name}</strong><span>{row.total}</span><span>{row.answerRate}</span><span>{row.qualRate}</span><span>{row.meetRate}</span></div>)}</div></section></div><section className="analytics-card"><div className="section-heading"><div><h2>Leitura dos dados</h2><span>Sem extrapolar resultados não registrados</span></div></div><div className="insight-grid"><div><strong>{base.filter((l) => !hasChannel(l)).length}</strong><span>empresas sem o canal selecionado</span></div><div><strong>{countStatus(advanced)}</strong><span>respostas registradas na seleção</span></div><div><strong>{countStatus(qualified)}</strong><span>qualificações registradas</span></div><div><strong>{countStatus(meetings)}</strong><span>avanços para reunião ou além</span></div></div></section></div> }

function HuntPage({ results, selected, setSelected, onSearch, onAdd, onOpen, preset }: { results: HuntedLead[]; selected: string[]; setSelected: (ids: string[]) => void; onSearch: (segment: string, location: string, quantity: number) => Promise<{ found: number; unique: number }>; onAdd: () => void; onOpen: (item: HuntedLead) => void; preset?: { segment: string; location: string } }) { const [segment, setSegment] = useState(preset?.segment || "refrigeração"); const [location, setLocation] = useState(preset?.location || "Belém"); const [quantity, setQuantity] = useState(20); const [loading, setLoading] = useState(false); const [summary, setSummary] = useState(""); const [error, setError] = useState(""); useEffect(() => { if (preset) { setSegment(preset.segment); setLocation(preset.location); } }, [preset]); async function submit(e: FormEvent) { e.preventDefault(); setLoading(true); setError(""); try { const r = await onSearch(segment, location, quantity); setSummary(`${r.found} encontradas · ${r.unique} novas · ${r.unique ? "selecione e adicione as melhores" : "nenhum resultado novo"}`); } catch (err) { setError(err instanceof Error ? err.message : "Falha na busca"); } finally { setLoading(false); } } return <div className="page-content"><section className="hero-row"><div><div className="eyebrow"><Search size={13} /> DESCOBERTA DE NOVOS CONTATOS</div><h1>Caçar <em>Leads.</em></h1><p>Encontre empresas públicas por segmento e região, revise os resultados e adicione somente as melhores oportunidades.</p></div><div className="hero-tip"><div className="tip-icon"><Target size={17} /></div><div><span>Fluxo seguro</span><strong>Pesquisar · revisar · adicionar</strong><small>Duplicados são removidos antes da carteira</small></div></div></section><form className="hunt-form" onSubmit={submit}><label>Buscar segmento<input value={segment} onChange={(e) => setSegment(e.target.value)} placeholder="Ex.: empresas de refrigeração" /></label><label>Cidade ou região<input value={location} onChange={(e) => setLocation(e.target.value)} placeholder="Belém" /></label><label>Quantidade<input type="number" min="1" max="50" value={quantity} onChange={(e) => setQuantity(Number(e.target.value))} /></label><button className="dark-action" disabled={loading}>{loading ? "Pesquisando..." : <><Search size={15} /> Pesquisar</>}</button></form>{error && <div className="import-summary error-summary">{error}</div>}{summary && <div className="import-summary">{summary}</div>}<section className="hunt-results"><div className="section-heading"><div><h2>Resultados para revisão</h2><span>{results.length} empresas novas · selecione antes de adicionar</span></div>{results.length > 0 && <button className="dark-action" onClick={onAdd}><Plus size={15} /> Adicionar selecionadas ({selected.length})</button>}</div>{results.map((item) => <article className="hunt-card" key={item.id}><input type="checkbox" checked={selected.includes(item.id)} onChange={(e) => setSelected(e.target.checked ? [...selected, item.id] : selected.filter((id) => id !== item.id))} /><div className="hunt-main"><h3>{item.name}</h3><span>{item.segment} · {item.location}</span><p>{item.phone ? `Telefone: ${item.phone}` : "Telefone não identificado"} · {item.whatsapp ? "WhatsApp provável" : "WhatsApp não identificado"}{item.site ? ` · ${item.site}` : ""}</p></div><div><small>Score</small><strong className="hunt-score">{item.score}</strong></div><div><small>Oportunidade</small><strong>{item.opportunity}</strong></div><div><small>Fonte</small><a href={item.sourceUrl} target="_blank" rel="noreferrer" onClick={() => onOpen(item)}>{item.sourceTitle.slice(0, 28)}</a></div></article>)}{!results.length && <div className="empty-state"><Search size={23} /><strong>Comece uma busca</strong><span>Informe segmento, cidade e quantidade desejada.</span></div>}</section></div> }

function Today({ best, queue, stats, onSelect, onOpen, onPrepare, onNavigate }: { best?: Lead; queue: Lead[]; stats: { total: number; high: number; contacted: number; replies: number; meetings: number }; onSelect: (lead: Lead) => void; onOpen: (lead: Lead) => void; onPrepare: (lead: Lead) => void; onNavigate: (tab: Tab) => void }) { const due = queue.filter(isDue).length; const today = queue.filter(isToday).length; const pending = queue.filter((l) => l.status === "Respondeu").length; return <div className="page-content"><section className="hero-row"><div><div className="eyebrow"><Sparkles size={13} /> CENTRO DE COMANDO · HOJE</div><h1>Saiba o que fazer <em>agora.</em></h1><p>Uma fila operacional baseada nos seus contatos, status, score, histórico e próximas ações.</p></div><div className="hero-tip"><div className="tip-icon"><Target size={17} /></div><div><span>Próxima melhor ação</span><strong>{best ? best.name : "Nenhuma pendência"}</strong><small>{best ? priorityReason(best) : "Cadastre uma empresa"}</small></div></div></section><section className="metric-grid"><Metric title="Prontos para abordar" value={stats.high} icon={<Target size={17} />} /><Metric title="Follow-ups vencidos" value={due} icon={<ArrowUpRight size={17} />} /><Metric title="Follow-ups de hoje" value={today} icon={<Send size={17} />} /><Metric title="Respostas pendentes" value={pending} icon={<MessageCircle size={17} />} /></section>{best && <section className="today-next"><div className="section-heading"><div><h2>Próxima melhor ação</h2><span>Por que este lead? {priorityReason(best)}</span></div><span className="priority high">{scoreLabel(best.score)}</span></div><div className="next-card"><div className="avatar avatar-lime">{best.initials}</div><div className="next-main"><h3>{best.name}</h3><p><strong>Oportunidade:</strong> {best.intelligence?.opportunities[0]}</p><p><strong>Dor provável:</strong> {best.intelligence?.probablePains[0]}</p><p><strong>Ação:</strong> {best.status === "Respondeu" ? "Responder e qualificar" : best.status === "Reunião" ? "Preparar reunião" : isDue(best) ? "Fazer follow-up vencido" : "Enviar abordagem inicial"}</p><small>{best.intelligence?.confidence}% de confiança · {best.intelligence?.scoreReasons.join(" · ")}</small></div><div className="lead-score"><span>Score</span><strong>{best.score}</strong></div><div className="next-actions"><button className="dark-action" onClick={() => onPrepare(best)}><Sparkles size={15} /> Gerar abordagem</button><button className="whatsapp-button" onClick={() => onOpen(best)}><MessageCircle size={15} /> Abrir WhatsApp</button><button className="outline-button" onClick={() => onSelect(best)}>Raio-X</button></div></div></section>}<section className="today-next"><div className="section-heading"><div><h2>Fila de hoje</h2><span>{queue.length} próximas ações ordenadas automaticamente</span></div><button className="outline-button" onClick={() => onNavigate("leads")}>Ver pipeline <ArrowUpRight size={14} /></button></div><div className="today-queue">{queue.map((lead, index) => <div className="queue-row" key={lead.id}><b>{String(index + 1).padStart(2, "0")}</b><div><strong>{lead.name}</strong><small>{lead.segment} · {lead.intelligence?.opportunities[0]}</small></div><span className="queue-action">{isDue(lead) ? "Follow-up vencido" : lead.status === "Respondeu" ? "Responder" : "Abordar"}</span><span className="queue-score">{lead.score}</span><button className="outline-button" onClick={() => onSelect(lead)}>Abrir</button><button className="whatsapp-button" onClick={() => onOpen(lead)}><MessageCircle size={14} /> WhatsApp</button></div>)}</div></section><section className="today-grid"><button className="today-tile" onClick={() => onNavigate("leads")}><Users size={19} /><strong>{stats.total} empresas no pipeline</strong><span>Ver leads e ajustar filtros</span></button><button className="today-tile" onClick={() => onNavigate("opportunities")}><Target size={19} /><strong>{stats.high} oportunidades prioritárias</strong><span>Comparar dor, serviço e próxima ação</span></button><button className="today-tile" onClick={() => onNavigate("scripts")}><MessageCircle size={19} /><strong>Playbook contextual</strong><span>Mensagens curtas para iniciar conversa</span></button></section></div> }

function Metric({ title, value, icon }: { title: string; value: number; icon: React.ReactNode }) { return <div className="metric-card"><div className="metric-top"><span>{title}</span>{icon}</div><strong>{value}</strong><small>baseado em registros reais do pipeline</small></div> }
function CalendarIcon() { return <ArrowUpRight size={17} />; }

function LeadsPage({ filtered, stats, query, setQuery, segment, setSegment, priority, setPriority, statuses, updateStatus, openWhatsApp, setSelectedLead, setShowAddLead, handleCsvImport, importSummary }: any) { return <div className="page-content"><section className="hero-row"><div><div className="eyebrow"><LayoutDashboard size={13} /> PIPELINE COMERCIAL</div><h1>Leads com <em>contexto.</em></h1><p>Filtre empresas, entenda o sinal observado e escolha a próxima ação.</p></div></section><section className="toolbar-section"><div className="section-heading"><div><h2>Empresas para trabalhar</h2><span>{filtered.length} filtradas · score e oportunidades explicáveis</span></div><div className="heading-actions"><label className="outline-button upload-button"><Upload size={15} /> Importar CSV<input type="file" accept=".csv,text/csv" onChange={handleCsvImport} /></label><button className="dark-action" onClick={() => setShowAddLead(true)}><Plus size={15} /> Nova empresa</button></div></div>{importSummary && <div className="import-summary">Importação: {importSummary}</div>}<div className="filters-row"><label className="search-field"><Search size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar empresa, segmento ou dor..." /></label><div className="filter-pills"><button className={segment === "Todos" ? "filter-pill selected" : "filter-pill"} onClick={() => setSegment("Todos")}>Todos <b>{stats.total}</b></button>{(["Serviços", "Imobiliárias", "Distribuidoras"] as Segment[]).map((s) => <button key={s} className={segment === s ? "filter-pill selected" : "filter-pill"} onClick={() => setSegment(s)}>{s}</button>)}</div><label className="select-field"><span>Prioridade</span><select value={priority} onChange={(e) => setPriority(e.target.value)}><option>Todas</option><option>Alta</option><option>Média</option></select><ChevronDown size={15} /></label></div></section><section className="lead-list">{filtered.map((lead: Lead, index: number) => <article className="lead-card" key={lead.id}><div className={`avatar avatar-${lead.color}`}>{lead.initials}</div><div className="lead-main"><div className="lead-title-row"><h3>{lead.name}</h3><span className={`priority ${lead.priority === "Alta" ? "high" : "medium"}`}>{lead.demo ? "DEMO · " : ""}{lead.priority}</span></div><div className="lead-meta"><span>{lead.segment} · {lead.intelligence?.subsegment}</span><span className="meta-separator">·</span><span>{lead.location}</span>{lead.site && <span className="site-meta"><Globe2 size={12} /> {lead.site}</span>}</div><div className="contact-hints"><span><Phone size={11} /> {lead.phone}</span>{lead.email && <span><Mail size={11} /> {lead.email}</span>}</div><p className="opportunity"><strong>Dor provável:</strong> {lead.intelligence?.probablePains[0]} <span className="opportunity-arrow">→</span> {lead.intelligence?.opportunities[0]}</p></div><div className="lead-score"><span>Score</span><strong>{lead.score}</strong><div className="score-bar"><i style={{ width: `${lead.score}%` }} /></div></div><div className="lead-actions"><label className="status-select"><select value={statuses[lead.id] || "Novo"} onChange={(e) => updateStatus(lead.id, e.target.value)}>{statusOptions.map((s) => <option key={s}>{s}</option>)}</select><ChevronDown size={13} /></label><button className="whatsapp-button" onClick={() => openWhatsApp(lead)}><MessageCircle size={16} /> WhatsApp</button><button className="more-button" onClick={() => setSelectedLead(lead)}><MoreHorizontal size={18} /></button></div></article>)}{!filtered.length && <div className="empty-state"><Search size={23} /><strong>Nenhuma empresa encontrada</strong><span>Importe, cadastre ou limpe os filtros.</span></div>}</section></div> }

function Opportunities({ leads, statuses, onSelect, onOpen, onHunt }: { leads: Lead[]; statuses: Record<string, LeadStatus>; onSelect: (lead: Lead) => void; onOpen: (lead: Lead) => void; onHunt: (lead: Lead) => void }) { return <div className="page-content"><section className="hero-row"><div><div className="eyebrow"><Target size={13} /> OPORTUNIDADES COMERCIAIS</div><h1>Onde existe <em>potencial.</em></h1><p>Não é uma lista de ERP: é a relação entre sinal, dor provável, oportunidade e serviço sugerido.</p></div></section><div className="opportunity-list">{[...leads].sort((a, b) => b.score - a.score).map((lead) => <article className="opportunity-row" key={lead.id} onClick={() => onSelect(lead)}><div><span className="eyebrow">{lead.segment} · {lead.intelligence?.subsegment}</span><h3>{lead.name}</h3></div><div><small>Dor provável</small><strong>{lead.intelligence?.probablePains[0]}</strong></div><div><small>Oportunidade encontrada</small><strong>{lead.intelligence?.opportunities[0]}</strong></div><div><small>Serviço sugerido</small><strong>{lead.intelligence?.recommendedServices[0]}</strong></div><div className="lead-score"><span>Score</span><strong>{lead.score}</strong></div><button className="outline-button" onClick={(e) => { e.stopPropagation(); onHunt(lead); }}><Search size={14} /> Encontrar parecidas</button><button className="whatsapp-button" onClick={(e) => { e.stopPropagation(); onOpen(lead); }}><MessageCircle size={15} /> Abordar</button></article>)}</div></div> }

function Scripts({ onCopy, copied }: { onCopy: (key: string, text: string) => void; copied: string | null }) { const examples = [{ title: "Primeiro contato", text: "Oi, responsável pela [empresa]. Vi que vocês trabalham com [sinal observado]. Hoje vocês controlam [dor provável] por onde?" }, { title: "Follow-up 1", text: "Oi, retomando nossa conversa. Fiquei curioso sobre como vocês organizam [dor provável]. Posso compartilhar uma ideia em 10 minutos?" }, { title: "Qualificação", text: "Para entender melhor: o que mais gera retrabalho hoje — atendimento, equipe, estoque ou retorno de orçamento?" }, { title: "Agendamento", text: "Pelo que você comentou, vale uma conversa rápida. Tenho [dia/horário] ou [dia/horário]. Qual funciona melhor?" }]; return <div className="page-content scripts-page"><section className="hero-row"><div><div className="eyebrow"><MessageCircle size={13} /> PLAYBOOK CONTEXTUAL</div><h1>Mensagens que abrem <em>conversa.</em></h1><p>Use o sinal observado antes da oferta. O objetivo do primeiro contato é gerar resposta, não fechar tudo.</p></div></section><div className="script-panel">{examples.map((example, index) => <div className="script-message" key={example.title}><div className="message-index">0{index + 1}</div><div className="message-body"><div className="message-head"><span>{example.title}</span><button onClick={() => onCopy(`script-${index}`, example.text)}>{copied === `script-${index}` ? <><Check size={14} /> Copiado</> : <><Clipboard size={14} /> Copiar</>}</button></div><p>{example.text}</p></div></div>)}</div></div> }

function LeadModal({ lead, status, onClose, onOpen, onPrepare, onCopy, copied, onStatus, onUpdate, onSchedule, onResearch, onHunt }: { lead: Lead; status: LeadStatus; onClose: () => void; onOpen: (lead: Lead) => void; onPrepare: (lead: Lead) => void; onCopy: (key: string, text: string) => void; copied: string | null; onStatus: (id: string, status: LeadStatus) => void; onUpdate: (id: string, patch: Partial<Lead>) => void; onSchedule: (lead: Lead, days: number) => void; onResearch: (lead: Lead) => void; onHunt: (lead: Lead) => void }) { const intel = lead.intelligence ?? analyzeLead(lead); const [note, setNote] = useState(lead.notes || ""); return <div className="modal-backdrop" onClick={onClose}><div className="lead-modal lead-xray" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={onClose}><X size={18} /></button><div className={`avatar avatar-${lead.color}`}>{lead.initials}</div><span className="modal-kicker">RAIO-X DA EMPRESA · {lead.demo ? "DEMO" : "REGISTRO"}</span><h2>{lead.name}</h2><p className="modal-opportunity">{lead.segment} · {intel.subsegment} · {intel.businessModel}</p><div className="research-callout"><div><strong>Inteligência externa</strong><span>{lead.research ? `Pesquisa concluída em ${formatDate(lead.research.lastResearchAt)} · ${lead.research.sources.length} fonte(s) · ${lead.research.signals.length} sinal(is)` : "Poucos sinais pesquisados neste lead."}</span></div><button className="outline-button" onClick={() => onResearch(lead)}><Globe2 size={14} /> {lead.research ? "Pesquisar novamente" : "Pesquisar empresa"}</button></div>{(lead.research?.sources || []).map((source) => <div className="evidence-row" key={source.id}><div><b>FATO PESQUISADO</b><span>{source.claim}</span><small>{source.sourceTitle} · confiança {source.confidence}</small></div><a href={source.sourceUrl} target="_blank" rel="noreferrer">Ver fonte</a></div>)}{lead.research?.signals?.length ? <div className="researched-signals"><h4>SINAIS ENCONTRADOS</h4>{lead.research.signals.map((signal) => <span key={signal}>{signal}</span>)}</div> : null}<div className="xray-grid"><section><h4>OBSERVADO</h4><ul>{intel.observedSignals.map((x) => <li key={x}>{x}</li>)}</ul></section><section><h4>PROVÁVEL</h4><ul>{intel.probablePains.map((x) => <li key={x}>{x}</li>)}</ul></section><section><h4>OPORTUNIDADE</h4><ul>{intel.opportunities.map((x) => <li key={x}>{x}</li>)}</ul></section><section><h4>RECOMENDADO</h4><ul>{intel.recommendedServices.map((x) => <li key={x}>{x}</li>)}</ul></section></div><div className="score-explanation"><strong>{lead.score}/100 · {intel.confidence}% de confiança</strong><span>Por que este lead? {intel.scoreReasons.join(" · ")}</span></div><div className="next-action-box"><strong>Próxima ação: {status === "Respondeu" ? "responder e qualificar" : status === "Reunião" ? "preparar reunião" : "abordar empresa"}</strong><label>Status<select value={status} onChange={(e) => onStatus(lead.id, e.target.value as LeadStatus)}>{statusOptions.map((s) => <option key={s}>{s}</option>)}</select></label></div><div className="message-variants"><h4>ABORDAGEM CONTEXTUAL</h4>{Object.entries(buildVariants(lead)).map(([kind, text]) => <div key={kind}><b>{kind}</b><p>{text}</p><button className="outline-button" onClick={() => onCopy(`variant-${lead.id}-${kind}`, text)}>{copied === `variant-${lead.id}-${kind}` ? "Copiado" : "Copiar"}</button></div>)}</div><label className="notes-box">Notas comerciais<textarea value={note} onChange={(e) => setNote(e.target.value)} onBlur={() => onUpdate(lead.id, { notes: note })} placeholder="Usa planilha; sócio decide; pediu retorno..." /></label><div className="timeline"><h4>HISTÓRICO</h4>{(lead.events || []).slice(-5).reverse().map((event) => <div key={event.id}><b>{formatDate(event.at)}</b><span>{event.type}</span></div>)}{!(lead.events || []).length && <small>Nenhum evento registrado ainda.</small>}</div><div className="context-actions"><button className="outline-button" onClick={() => onHunt(lead)}><Search size={14} /> Encontrar empresas parecidas</button></div><div className="followup-actions"><span>Programar follow-up</span><button onClick={() => onSchedule(lead, 1)}>Amanhã</button><button onClick={() => onSchedule(lead, 2)}>2 dias</button><button onClick={() => onSchedule(lead, 3)}>3 dias</button><button onClick={() => onSchedule(lead, 7)}>7 dias</button></div><div className="modal-actions"><button className="dark-action" onClick={() => onPrepare(lead)}><Sparkles size={15} /> Gerar abordagem</button><button className="whatsapp-button large" onClick={() => onOpen(lead)}><MessageCircle size={17} /> Abrir WhatsApp</button><button className="outline-button" onClick={() => onStatus(lead.id, "Mensagem enviada")}><Check size={14} /> Marcar enviada</button><button className="outline-button" onClick={() => onCopy(`modal-${lead.id}`, buildMessage(lead, "primeiro contato"))}>{copied === `modal-${lead.id}` ? "Copiado" : "Copiar mensagem"}</button></div></div></div> }
